// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/api/v1/groups/:groupId/outings", wrapper.CreateOuting)
	router.GET(options.BaseURL+"/api/v1/outings/:outingId", wrapper.GetOuting)
	router.GET(options.BaseURL+"/api/v1/outings/:outingId/invitations", wrapper.GetOutingInvitations)
	router.GET(options.BaseURL+"/api/v1/me/invitations", wrapper.GetMyInvitations)
	router.PUT(options.BaseURL+"/api/v1/outings/:outingId/invitations/:phase", wrapper.RespondOuting)
	router.POST(options.BaseURL+"/api/v1/groups", wrapper.CreateGroup)
	router.POST(options.BaseURL+"/api/v1/groups/join", wrapper.JoinGroup)
	router.GET(options.BaseURL+"/api/v1/groups/:groupId", wrapper.GetGroup)
	router.GET(options.BaseURL+"/api/v1/groups/:groupId/members", wrapper.GetGroupMembers)
	router.POST(options.BaseURL+"/api/v1/auth/register", wrapper.Register)
	router.POST(options.BaseURL+"/api/v1/auth/login", wrapper.Login)
	router.POST(options.BaseURL+"/api/v1/auth/logout", wrapper.Logout)
	router.GET(options.BaseURL+"/api/v1/profile", wrapper.GetProfile)
	router.PUT(options.BaseURL+"/api/v1/profile", wrapper.PutProfile)
	router.GET(options.BaseURL+"/api/v1/preferences", wrapper.GetPreferences)
	router.PUT(options.BaseURL+"/api/v1/preferences", wrapper.PutPreferences)
	router.GET(options.BaseURL+"/api/v1/me", wrapper.Me)
	router.GET(options.BaseURL+"/healthz", wrapper.Health)
	router.GET(options.BaseURL+"/readyz", wrapper.Ready)
}
